/**
 * Signals in message BMS_Status.
 *
 * BMS state, BMS_OK and BMS faults. Every sweep (20 ms), from the first control step. E2E Profile 11, Data ID 0x0080. Only a BMS image sends this ID, so the ID also says which image a board runs.
Layout: byte 0 CRC; byte 1 counter (bits 0-3) and state (bits 4-7); bytes 2-3 one active bit per fault; bytes 4-5 one seen bit per fault, same order; byte 6 flags that are not faults; byte 7 Control bus trouble, never a fault (ADR 0005).
Fault order in both bit rows: 0 over-voltage, 1 under-voltage, 2 over-temperature, 3 under-temperature, 4 measurement, 5 open wire, 6 cell monitor, 7 internal, 8 charger disobeys, 9 overcurrent; 10-15 spare.
 *
 * All signal values are as on the CAN bus.
 */
struct can_control_bms_status_t {
    /**
     * E2E Profile 11 CRC-8 over the Data ID and bytes 1-7.
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t crc;

    /**
     * E2E Profile 11 counter, 0 to 14.
     *
     * Range: 0..14 (0..14 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t counter;

    /**
     * BMS state. FAULT ends by itself after 1 s clean; FAULT_HELD lasts until a power-on reset.
     *
     * Range: 0..4 (0..4 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t state;

    /**
     * Active bits: the fault exists now, after its debounce. Cell over-voltage.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t over_voltage_active;

    /**
     * Cell under-voltage.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t under_voltage_active;

    /**
     * Cell over-temperature.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t over_temp_active;

    /**
     * Cell under-temperature. Charge mode only.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t under_temp_active;

    /**
     * Measurement missing or invalid, or cell-monitor chain comms loss.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t measurement_active;

    /**
     * Open sense wire.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t open_wire_active;

    /**
     * Cell monitor fault: NFAULT low, a device fault, or a comparator.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cell_monitor_active;

    /**
     * BMS internal fault: Held fault after a reset that was not power-on, feedback mismatch, sense cross-check, timing fault. The cause is in the Event log.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t internal_active;

    /**
     * Charger disobeys its request.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t charger_disobeys_active;

    /**
     * Reserved, never set (pack current sensing, issue 29).
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t overcurrent_active;

    /**
     * Seen bits: the fault has tripped since power-up; cleared only by a power cycle. Same order as the active bits.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t over_voltage_seen;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t under_voltage_seen;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t over_temp_seen;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t under_temp_seen;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t measurement_seen;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t open_wire_seen;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cell_monitor_seen;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t internal_seen;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t charger_disobeys_seen;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t overcurrent_seen;

    /**
     * The level the firmware commands on BMS_OK: 1 = high (no fault).
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bms_ok;

    /**
     * A cell is under the Low-voltage limit (3.0 V) and the Discharge limit is being derated. Not a fault.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t low_voltage_limit;

    /**
     * The Shutdown Circuit sense input reads energised (in the car or on the hand cart).
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t shutdown_circuit_closed;

    /**
     * Charge complete: lasts until a power cycle.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t charge_complete;

    /**
     * No valid stored parameters were found; running on defaults.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t parameters_defaulted;

    /**
     * The MCU is not in dual-bank mode; nothing is written to flash.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t not_dual_bank;

    /**
     * The last reset was not a power-on reset.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t last_reset_not_power_on;

    /**
     * Third bus-off without 1 s clean; retrying once per second.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bus_off_latched;

    /**
     * The CAN1 controller is error-passive.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t error_passive;

    /**
     * A CAN1 receive FIFO has overflowed since power-up.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t receive_overflow;
};

/**
 * Signals in message BMS_Limits.
 *
 * Charge limit and pack voltage. Every 100 ms. E2E Profile 11, Data ID 0x0081. Bytes 2-3 charge limit, bytes 4-5 pack voltage, bytes 6-7 and bits 4-7 of byte 1 spare.
 *
 * All signal values are as on the CAN bus.
 */
struct can_control_bms_limits_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t crc;

    /**
     * Range: 0..14 (0..14 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t counter;

    /**
     * Charge limit. 0 A in DRIVE and until BMS_OK is up.
     *
     * Range: 0..65535 (0..6553.5 A)
     * Scale: 0.1
     * Offset: 0
     */
    uint16_t charge_limit;

    /**
     * Sum of the cell voltages of the last sweep.
     *
     * Range: 0..65535 (0..6553.5 V)
     * Scale: 0.1
     * Offset: 0
     */
    uint16_t pack_voltage;
};

/**
 * Signals in message BMS_Power.
 *
 * Pack current, pack voltage and Discharge limit, all from one sweep. Every sweep (20 ms). E2E Profile 11, Data ID 0x0082. Bits 4-7 of byte 1 are spare: issue 29 (pack current sensing) decides how an invalid current is marked.
 *
 * All signal values are as on the CAN bus.
 */
struct can_control_bms_power_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t crc;

    /**
     * Range: 0..14 (0..14 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t counter;

    /**
     * Pack current, positive when discharging.
     *
     * Range: -32768..32767 (-3276.8..3276.7 A)
     * Scale: 0.1
     * Offset: 0
     */
    int16_t pack_current;

    /**
     * Sum of the cell voltages of the same sweep.
     *
     * Range: 0..65535 (0..6553.5 V)
     * Scale: 0.1
     * Offset: 0
     */
    uint16_t pack_voltage;

    /**
     * Derated Discharge limit (ADR 0018). 0 A until BMS_OK is up.
     *
     * Range: 0..65535 (0..6553.5 A)
     * Scale: 0.1
     * Offset: 0
     */
    uint16_t discharge_limit;
};

/**
 * Signals in message VCU_Status.
 *
 * VCU state, fault bits, flags and the torque sent. Every second control step (20 ms), from the first step. E2E Profile 11, Data ID 0x0090. Only a VCU image sends this ID, so the ID also says which image a board runs.
Layout: byte 0 CRC; byte 1 counter (bits 0-3) and state (bits 4-7); byte 2 Torque cut causes; byte 3 causes of Leaving Ready to Drive or of a refused start; byte 4 reported only; byte 5 flags; bytes 6-7 torque.
This replaces the layout first drawn on issue 13 (state in byte 2, 16 fault bits in bytes 3-4), which later decisions over-filled. The state moved into the free half of byte 1, which gives three bytes of bits, and the timing fault sits with the other Torque cut causes instead of in the flags byte. Spare: bits 6-7 of byte 3, bit 7 of byte 4, bits 4-7 of byte 5.
 *
 * All signal values are as on the CAN bus.
 */
struct can_control_vcu_status_t {
    /**
     * E2E Profile 11 CRC-8 over the Data ID and bytes 1-7.
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t crc;

    /**
     * E2E Profile 11 counter, 0 to 14.
     *
     * Range: 0..14 (0..14 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t counter;

    /**
     * VCU state. There is no fault state and no separate Ready to Drive bit.
     *
     * Range: 0..3 (0..3 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t state;

    /**
     * Torque cut: the two pedal sensors disagree or one is out of range.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t apps_implausible;

    /**
     * Torque cut: a brake pressure sensor is out of range.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t brake_sensor_failed;

    /**
     * Torque cut: Brake engaged with Pedal travel above 25%.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t brake_pedal_cut;

    /**
     * Torque cut: the BMS_Status mailbox is not VALID.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bms_status_timeout;

    /**
     * Torque cut: the BMS_Limits mailbox is not VALID.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bms_limits_timeout;

    /**
     * Torque cut: the BMS_Power mailbox is not VALID.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bms_power_timeout;

    /**
     * Torque cut: an inverter mailbox is not VALID.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t inverter_timeout;

    /**
     * Torque cut: three Overruns within one second.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t timing_fault;

    /**
     * BMS_Status reports a fault.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bms_fault_reported;

    /**
     * The inverter reports a fault (INV_FaultCodes).
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t inverter_fault_reported;

    /**
     * The Shutdown Circuit input reads open.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t shutdown_circuit_open;

    /**
     * Third bus-off without 1 s clean; clears after 5 s clean.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bus_off_latched;

    /**
     * No valid stored parameters: not calibrated, no torque, Start procedure refused.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t parameters_defaulted;

    /**
     * A start-up check has not passed and the VCU is staying in STARTUP.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t startup_blocked;

    /**
     * The pedal and brake calibration is not Calibrated (ADR 0016): APPS implausible, no torque, Start procedure refused.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t not_calibrated;

    /**
     * No Pedal check has passed for this image and these parameters (ADR 0016): Start procedure refused.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t pedal_check_due;

    /**
     * The EM_Measurement mailbox is not VALID. Cuts nothing.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t energy_meter_timeout;

    /**
     * The CAN1 controller is error-passive.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t error_passive;

    /**
     * A CAN1 receive FIFO has overflowed since power-up.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t receive_overflow;

    /**
     * The bus was still above 60 V 5 s after the Shutdown Circuit opened.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t discharge_slow;

    /**
     * The torque sent is under the driver's request because of the Power limiter, whichever of its two ceilings is the lower.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t limiter_active;

    /**
     * The last reset was not a power-on reset.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t last_reset_not_power_on;

    /**
     * The MCU is not in dual-bank mode; nothing is written to flash.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t not_dual_bank;

    /**
     * Brake engaged.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t brake_engaged;

    /**
     * The start button reads pressed.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t start_button;

    /**
     * The Ready to Drive sound is on.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t sound_on;

    /**
     * The last INV_Command carried Enable = 1.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t enable_sent;

    /**
     * The torque in the last INV_Command.
     *
     * Range: -32768..32767 (-3276.8..3276.7 Nm)
     * Scale: 0.1
     * Offset: 0
     */
    int16_t torque_sent;
};

/**
 * Signals in message INV_MotorPosition.
 *
 * Inverter 0x0A5 Motor Position Information. CM manual Table 59, p.144. UNVERIFIED: layout not yet checked against a bus capture. Set to the fast broadcast rate (10 ms) at commissioning.
 *
 * All signal values are as on the CAN bus.
 */
struct can_control_inv_motor_position_t {
    /**
     * INV_Motor_Speed, bytes 2-3, Angular Velocity format (1 rpm). Table 59, p.144; format p.84.
     *
     * Range: -32768..32767 (-32768..32767 rpm)
     * Scale: 1
     * Offset: 0
     */
    int16_t motor_speed;
};

/**
 * Signals in message INV_Voltage.
 *
 * Inverter 0x0A7 Voltage Information. CM manual Table 61, p.144. UNVERIFIED: layout not yet checked against a bus capture. Fast rate (10 ms).
 *
 * All signal values are as on the CAN bus.
 */
struct can_control_inv_voltage_t {
    /**
     * INV_DC_Bus_Voltage, bytes 0-1, High Voltage format (0.1 V). Table 61, p.144; format p.84.
     *
     * Range: -32768..32767 (-3276.8..3276.7 V)
     * Scale: 0.1
     * Offset: 0
     */
    int16_t dc_bus_voltage;
};

/**
 * Signals in message INV_InternalStates.
 *
 * Inverter 0x0AA Internal States. CM manual Table 64, p.145-148. UNVERIFIED: layout not yet checked against a bus capture. Fast rate (10 ms).
 *
 * All signal values are as on the CAN bus.
 */
struct can_control_inv_internal_states_t {
    /**
     * INV_VSM_State, byte 0. Table 64, p.145.
     *
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t vsm_state;

    /**
     * INV_Inverter_Enable_State, byte 6 bit 0: 1 enabled. Table 64, p.147.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t enable_state;

    /**
     * INV_Inverter_Enable_Lockout, byte 6 bit 7: 1 = cannot be enabled until a command with Enable = 0 is seen. Table 64, p.148.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t enable_lockout;

    /**
     * INV_BMS_Active, byte 7 bit 1: the 0x202 frame is being received. Table 64, p.148.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bms_active;

    /**
     * INV_BMS_Limiting_Motor_Torque, byte 7 bit 2. Table 64, p.148.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t bms_limiting_motor_torque;
};

/**
 * Signals in message INV_FaultCodes.
 *
 * Inverter 0x0AB Fault Codes. CM manual Table 65, p.149; bit meanings Tables 72-73, p.151-154. UNVERIFIED: layout not yet checked against a bus capture. Fast rate (10 ms).
 *
 * All signal values are as on the CAN bus.
 */
struct can_control_inv_fault_codes_t {
    /**
     * INV_Post_Fault_Lo (bytes 0-1) and _Hi (bytes 2-3) read as one 32-bit word. Table 65, p.149.
     *
     * Range: 0..4294967295 (0..4294967295 -)
     * Scale: 1
     * Offset: 0
     */
    uint32_t post_faults;

    /**
     * INV_Run_Fault_Lo (bytes 4-5) and _Hi (bytes 6-7) read as one 32-bit word. Table 65, p.149.
     *
     * Range: 0..4294967295 (0..4294967295 -)
     * Scale: 1
     * Offset: 0
     */
    uint32_t run_faults;
};

/**
 * Signals in message INV_TorqueCapability.
 *
 * Inverter 0x0B1 Torque Capability. CM manual Table 71, p.150. UNVERIFIED: layout not yet checked against a bus capture. Logged only.
 *
 * All signal values are as on the CAN bus.
 */
struct can_control_inv_torque_capability_t {
    /**
     * Motor Torque Available, bytes 0-1, Torque format (0.1 Nm). Table 71, p.150.
     *
     * Range: -32768..32767 (-3276.8..3276.7 Nm)
     * Scale: 0.1
     * Offset: 0
     */
    int16_t motor_torque_available;
};

/**
 * Signals in message INV_Command.
 *
 * Inverter 0x0C0 Command Message, in the inverter's format. CM manual Table 28, p.90, and Table 35, p.100 (rolling counter). UNVERIFIED: layout not yet checked against the inverter. Every VCU control step (10 ms) in every state after STARTUP. DLC must be 8 (p.90).
 *
 * All signal values are as on the CAN bus.
 */
struct can_control_inv_command_t {
    /**
     * Torque Command, bytes 0-1, Torque format. Never negative: no regen.
     *
     * Range: -32768..32767 (-3276.8..3276.7 Nm)
     * Scale: 0.1
     * Offset: 0
     */
    int16_t torque_command;

    /**
     * Speed Command, bytes 2-3. Speed mode only; always 0.
     *
     * Range: -32768..32767 (-32768..32767 rpm)
     * Scale: 1
     * Offset: 0
     */
    int16_t speed_command;

    /**
     * Direction Command, byte 4: 1 forward. Always 1.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t direction_command;

    /**
     * Inverter Enable, byte 5 bit 0. 1 only in READY_TO_DRIVE.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t inverter_enable;

    /**
     * Inverter Discharge, byte 5 bit 1. Never set: discharge is hardware-only.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t inverter_discharge;

    /**
     * Speed Mode Enable, byte 5 bit 2. Never set.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t speed_mode_enable;

    /**
     * Rolling Counter, byte 5 bits 4-7: last value + 1, modulo 16. Table 35, p.100; section 8.12, p.98-100.
     *
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t rolling_counter;

    /**
     * Commanded Torque Limit, bytes 6-7. Always the maximum-torque parameter, never a computed value. 0 means use the EEPROM limits, not zero torque (p.90).
     *
     * Range: 0..32767 (0..3276.7 Nm)
     * Scale: 0.1
     * Offset: 0
     */
    int16_t torque_limit;
};

/**
 * Signals in message INV_ParameterCommand.
 *
 * Inverter 0x0C1 Read/Write Parameter Command. CM manual Table 29, p.93. UNVERIFIED: layout not yet checked against the inverter. Sent once per start button press, only as a fault clear: address 20, write, data 0 (section 8.8.3, p.94).
 *
 * All signal values are as on the CAN bus.
 */
struct can_control_inv_parameter_command_t {
    /**
     * Parameter Address, bytes 0-1. 20 = Fault Clear (p.94).
     *
     * Range: 0..65535 (0..65535 -)
     * Scale: 1
     * Offset: 0
     */
    uint16_t parameter_address;

    /**
     * R/W Command, byte 2: 0 read, 1 write.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t write;

    /**
     * Data, bytes 4-5.
     *
     * Range: 0..65535 (0..65535 -)
     * Scale: 1
     * Offset: 0
     */
    uint16_t data;
};

/**
 * Signals in message EM_Measurement.
 *
 * Energy Meter 0x10D Measurement Message, sent by the meter every 20 ms. EM manual p.10. Logged only; nothing in the torque path reads it. The meter is fitted only at competition.
 *
 * All signal values are as on the CAN bus.
 */
struct can_control_em_measurement_t {
    /**
     * Current [A], float, bytes 0-3, little-endian. EM manual p.10.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    float current;

    /**
     * Voltage [V], float, bytes 4-7, little-endian. EM manual p.10.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    float voltage;
};

/**
 * Signals in message INV_BmsLimits.
 *
 * Inverter 0x202 BMS current limits, in the inverter's (Orion) format: fixed ID, whole amps, little-endian. CM manual section 8.10, p.96-97. UNVERIFIED: not yet checked against the inverter. Every 100 ms. The inverter drops the limit 1 s after the last frame. In Charge mode this frame gives up two of its ten slots per second to CHG_Request and BMS_Balancing.
 *
 * All signal values are as on the CAN bus.
 */
struct can_control_inv_bms_limits_t {
    /**
     * Maximum discharge current, bytes 0-1: the derated Discharge limit, unscaled. Section 8.10, p.96.
     *
     * Range: 0..32767 (0..32767 A)
     * Scale: 1
     * Offset: 0
     */
    uint16_t discharge_limit;

    /**
     * Maximum charge current, bytes 2-3. Section 8.10, p.96-97.
     *
     * Range: 0..32767 (0..32767 A)
     * Scale: 1
     * Offset: 0
     */
    uint16_t charge_limit;
};

